for (const { json: s } of $input.all()) { const r = s.resultat; if (!r || !r.a_relancer) continue; sortie.push({ json: env({ action_cle: r.cle_idempotence, faits: { ...FAITS[r.objet_id], palier: r.palier } }, { canal: CANAL[r.objet_type], ton: 'Exemple. cordial et simple, vouvoiement', signature: 'Exemple. L’équipe Bâti-Démo', nom_artisan: 'Exemple. Bâti-Démo', mention_ia: false }, sortie.length) }); }
