// Banc : chaque brouillon passe la porte, en carte à relire, avec les faits dont il est tiré (retrouvés par la clé de l'action, que
// lib-relancer a rendue). Destinataires fictifs : aucune opposition, aucun sujet d'escalade (déjà écartés par lib-relancer), consentement SMS donné.
const env = (donnees, config, n) => ({ contrat: 'lib-porte-conformite@1', organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: n, trace: { execution_parent: 'Exemple. banc relance', declencheur: 'banc', tentative: 0 }, config: config, donnees: donnees });
const FAITS = {"00000000-0000-4000-8000-000000000507":{"type_relance":"relance_facture","numero":"FAC-2026-007","objet":"Exemple. Mise aux normes électrique","montant_ttc_centimes":33400,"echeance_le":"2026-10-18","emis_le":"2026-09-18","regime_tva":"tva"},"00000000-0000-4000-8000-000000000508":{"type_relance":"relance_facture","numero":"FAC-2026-008","objet":"Exemple. Cuisine équipée","montant_ttc_centimes":29100,"echeance_le":"2026-10-24","emis_le":"2026-09-24","regime_tva":"tva"},"00000000-0000-4000-8000-000000000509":{"type_relance":"relance_facture","numero":"FAC-2026-009","objet":"Exemple. Isolation des combles","montant_ttc_centimes":45580,"echeance_le":"2026-10-30","emis_le":"2026-09-30","regime_tva":"tva"},"00000000-0000-4000-8000-000000000510":{"type_relance":"relance_facture","numero":"FAC-2026-010","objet":"Exemple. Rénovation salle de bain","montant_ttc_centimes":30840,"echeance_le":"2026-11-05","emis_le":"2026-10-06","regime_tva":"tva"},"00000000-0000-4000-8000-000000000311":{"type_relance":"relance_devis","numero":"DEV-2026-011","objet":"Exemple. Réfection de toiture","montant_ttc_centimes":36600,"emis_le":"2026-10-02","regime_tva":"tva"},"00000000-0000-4000-8000-000000000312":{"type_relance":"relance_devis","numero":"DEV-2026-012","objet":"Exemple. Mise aux normes électrique","montant_ttc_centimes":null,"emis_le":"2026-10-08","regime_tva":"tva"},"00000000-0000-4000-8000-000000000104":{"type_relance":"relance_conversation"},"00000000-0000-4000-8000-000000000106":{"type_relance":"relance_conversation"},"00000000-0000-4000-8000-000000000121":{"type_relance":"relance_conversation"},"00000000-0000-4000-8000-000000000125":{"type_relance":"relance_conversation"}};
const REGLES = {"jamais_auto":[],"regles_metier":{"fournisseurs":[],"mots_escalade_artisan":["Exemple. mot sensible"],"jours_permis":[1,2,3,4,5],"heures_permises":{"debut":"08:00","fin":"19:00"}},"plafond_jour":20};
const OUTIL = { relance_facture: 'relancer_facture', relance_devis: 'relancer_devis', relance_conversation: 'relancer_conversation' };
const RELANCES = $('Appeler lib-relancer').all().map((x) => x.json.resultat).filter((r) => r && r.a_relancer);
const sortie = [];
for (const { json: s } of $input.all()) {
  const b = s.resultat; if (!b) continue;
  const r = RELANCES.find((x) => x.cle_idempotence === b.action_cle); if (!r) continue;
  const f = { ...FAITS[r.objet_id], palier: r.palier };
  sortie.push({ json: env({ action: { type_action: f.type_relance, outil: OUTIL[f.type_relance], prix_sources: true, cible: 'carte', sans_relecture: false }, message: { canal: b.canal, objet: b.objet, texte: b.texte }, destinataire: { opposition: false, consentement_sms: true, escalade: false }, faits: f, maintenant: '2026-11-03T09:30:00.000+01:00', compteurs: { envoyes_aujourdhui: 0 } }, REGLES, b.action_cle) });
}
return sortie;

// Banc : ce que la porte laisse passer devient une carte prévue (mode A : niveau 2 au plus). Les interrupteurs sont ceux que relirait
// lib-executer juste avant l'effet (épinglés : ouverts) ; aucune clé n'est déjà en base. Ce que la porte refuse s'arrête ici, au journal.
const env = (donnees, config, n) => ({ contrat: 'lib-executer@1', organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: n, trace: { execution_parent: 'Exemple. banc relance', declencheur: 'banc', tentative: 0 }, config: config, donnees: donnees });
const RELANCES = $('Appeler lib-relancer').all().map((x) => x.json.resultat).filter((r) => r && r.a_relancer);
const BROUILLONS = $('Appeler lib-rediger-message').all().map((x) => x.json.resultat).filter(Boolean);
const sortie = [];
for (const { json: s } of $input.all()) {
  if (!s.resultat || s.resultat.verdict !== 'passe') continue;
  const r = RELANCES.find((x) => x.cle_idempotence === s.cle_idempotence), b = BROUILLONS.find((x) => x.action_cle === s.cle_idempotence);
  if (!r || !b) continue;
  sortie.push({ json: env({ verdict: 'passe', cible: s.resultat.cible, cle_idempotence: r.cle_idempotence, charge: { type_action: 'relance_' + r.objet_type, objet_type: r.objet_type, objet_id: r.objet_id, palier: r.palier, canal: b.canal, brouillon: { objet: b.objet, texte: b.texte } }, interrupteurs: { general: true, agent: true }, cles_existantes: [] }, { niveau_max: 2 }, r.cle_idempotence) });
}
return sortie;

// Banc : AU MOMENT D'ENVOYER (C4:144), et seulement là : une carte SMS validée par l'artisan partirait ; le numéro du destinataire est lu
// pour ce seul envoi (lecture prévue, épinglée : le numéro fictif du jeu, tranche 06 39 98) et normalisé. Rien n'est envoyé en mode A.
// Plus un numéro illisible (« Exemple. »), qui doit donner vide.
const env = (donnees, config, n) => ({ contrat: 'lib-normaliser-telephone@1', organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:normaliser-telephone:' + (n || 0), trace: { execution_parent: 'Exemple. banc relance', declencheur: 'banc', tentative: 0 }, config: config, donnees: donnees });
const NUMEROS = {"00000000-0000-4000-8000-000000000121":"06 39 98 00 06","00000000-0000-4000-8000-000000000125":"06 39 98 00 07"};
const sortie = [];
for (const { json: s } of $input.all()) { const e = (s.effets_prevus || [])[0]; if (!e || !e.corps || e.corps.canal !== 'sms') continue; sortie.push({ json: env({ moment: 'envoi', telephone: NUMEROS[e.corps.objet_id] ?? null }, {}, sortie.length) }); }
if (sortie.length) sortie.push({ json: env({ moment: 'envoi', telephone: 'Exemple. pas un numéro' }, {}, sortie.length) });
return sortie;

// Bilan agrégé, sans donnée : par contrat, le nombre de sorties par statut ; par verdict de la porte, le nombre par motif. Défaut : un effet
// fait en simulation, un appel en erreur, un geste « jamais en automatique » qui passe la porte en automatique, une ligne de rapport sans
// « Exemple. » ou avec un chiffre de gain, un numéro normalisé hors du moment d'envoyer.
const bilan = {}, porte = {};
let defauts = 0;
for (const { json: s } of $input.all()) {
  const c = typeof s.contrat === 'string' ? s.contrat : 'appel en erreur';
  bilan[c] = bilan[c] || {};
  const st = typeof s.statut === 'string' ? s.statut : 'erreur';
  bilan[c][st] = (bilan[c][st] || 0) + 1;
  if (!s.contrat || st === 'erreur' || (s.simulation === true && Array.isArray(s.effets_faits) && s.effets_faits.length)) defauts++;
  if (c === 'lib-porte-conformite@1' && s.resultat) {
    const k = s.resultat.verdict + ':' + (s.resultat.motifs.join('+') || s.resultat.cible);
    porte[k] = (porte[k] || 0) + 1;
    if (/^exemple:banc:geste:/.test(s.cle_idempotence) && s.resultat.verdict === 'passe') defauts++;
  }
  if (c === 'lib-rapport-hebdo@1' && s.resultat) for (const l of s.resultat.lignes) if (!/^Exemple\. /.test(l) || /gain|économi|gagn|€|retour sur investissement/i.test(l)) defauts++;
}
return [{ json: { bilan: bilan, porte: porte, defauts: defauts } }];

// Exemple. Chaque geste « jamais en automatique » du kit (liste du code PLUS p5:226, Amendement B1), demandé en AUTOMATIQUE (pilote, sans
// relecture), avec un message propre et sa mention d'IA, aux heures permises, sous le plafond : chacun doit être refusé (p5:315), repli
// en carte. Puis deux témoins : une relance de facture en automatique, propre (elle passe), et la même sans la mention (refusée).
const env = (donnees, config, n) => ({ contrat: 'lib-porte-conformite@1', organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: n, trace: { execution_parent: 'Exemple. banc relance', declencheur: 'banc', tentative: 0 }, config: config, donnees: donnees });
const GESTES = ["marquer_facture_payee","creer_facture","creer_facture_libre","rembourser","payer","creer_avoir","supprimer_devis_brouillon","supprimer_tarif","supprimer_article","augmenter_tarifs","envoyer_devis","envoi_devis","modifier_prix_sans_source","encaisser","toucher_moyen_paiement","declarer_urssaf","declarer_impots","supprimer_donnees","passer_appel","prendre_appel","prendre_rendez_vous"];
const REGLES = {"jamais_auto":[],"regles_metier":{"fournisseurs":[],"mots_escalade_artisan":["Exemple. mot sensible"],"jours_permis":[1,2,3,4,5],"heures_permises":{"debut":"08:00","fin":"19:00"}},"plafond_jour":20};
const MSG = {"canal":"email","objet":"Exemple. Votre dossier","texte":"{{salutation}}

Nous revenons vers vous au sujet de votre dossier. Il vous suffit de répondre à ce message pour toute question.

Bien cordialement,
Exemple. L’équipe Bâti-Démo

—
Message rédigé et envoyé automatiquement par l’assistant de Exemple. Bâti-Démo."};
const SANS = {"canal":"email","objet":"Exemple. Votre dossier","texte":"{{salutation}}

Nous revenons vers vous au sujet de votre dossier. Il vous suffit de répondre à ce message pour toute question.

Bien cordialement,
Exemple. L’équipe Bâti-Démo"};
const don = (outil, msg) => ({ action: { type_action: outil, outil: outil, prix_sources: true, cible: 'pilote', sans_relecture: true }, message: msg, destinataire: { opposition: false, consentement_sms: true, escalade: false }, faits: { type_relance: 'relance_facture', palier: 1 }, maintenant: '2026-11-03T09:30:00.000+01:00', compteurs: { envoyes_aujourdhui: 0 } });
const sortie = GESTES.map((g) => ({ json: env(don(g, MSG), REGLES, 'exemple:banc:geste:' + g) }));
sortie.push({ json: env(don('relancer_facture', MSG), REGLES, 'exemple:banc:temoin:relancer_facture') });
sortie.push({ json: env(don('relancer_facture', SANS), REGLES, 'exemple:banc:temoin:sans_mention') });
return sortie;

// Exemple. Le rapport du lundi 2 novembre 2026 pour la semaine du 26 octobre au 1er novembre : des actions fictives (aucune donnée),
// une base de départ déclarée par le client (jamais présentée comme mesurée), et une action hors période (non comptée).
const env = (donnees, config, n) => ({ contrat: 'lib-rapport-hebdo@1', organisation_id: '00000000-0000-4000-8000-000000000001', simulation: true, cle_idempotence: 'exemple:banc:rapport-hebdo:' + (n || 0), trace: { execution_parent: 'Exemple. banc relance', declencheur: 'banc', tentative: 0 }, config: config, donnees: donnees });
const A = (type_action, etat, le) => ({ type_action, etat, le });
const ACTIONS = [A('relance_facture', 'fait_seul', '2026-10-27T09:00:00.000+01:00'), A('relance_facture', 'fait_seul', '2026-10-28T09:00:00.000+01:00'), A('reponse_prospect', 'fait_seul', '2026-10-29T10:00:00.000+01:00'),
  A('relance_devis', 'en_attente', '2026-10-29T11:00:00.000+01:00'), A('relance_devis', 'en_attente', '2026-10-30T09:00:00.000+01:00'), A('relance_conversation', 'en_attente', '2026-10-30T15:00:00.000+01:00'), A('envoyer_devis', 'en_attente', '2026-10-31T09:00:00.000+01:00'),
  A('relance_facture', 'echec', '2026-10-31T10:00:00.000+01:00'), A('relance_devis', 'refuse_porte', '2026-11-01T09:00:00.000+01:00'), A('relance_facture', 'fait_seul', '2026-11-02T09:00:00.000+01:00')];
const KPIS = ["actions_preparees","relances_preparees","fait_seul","en_attente","echecs","refus_porte"];
return [{ json: env({ du: '2026-10-26', au: '2026-11-01', actions: ACTIONS }, { periode: 'semaine', kpis: KPIS, bases_de_depart: { relances_preparees: { valeur: 2, source: 'Exemple. fiche de découverte, dit par le gérant', date: '2026-10-01', confiance: 'declare' } } }, 1) }];
